def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive_opps = []
    prev_bids = []
    rich_aggressive = 0
    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opps.append(opp)
            prev = opp.get('previous_trace', {})
            bid = prev.get('bid') if prev else None
            if bid is not None:
                prev_bids.append(float(bid))
                if float(bid) >= 90 and opp.get('budget', 0) >= 200:
                    rich_aggressive += 1

    if not alive_opps:
        return min(float(budget), 18.0)

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    scarcity = (MAX_SUPPLY - float(supply)) / float(MAX_SUPPLY - MIN_SUPPLY)
    if scarcity < 0:
        scarcity = 0.0
    if scarcity > 1:
        scarcity = 1.0

    urgency = 0.0
    if hp <= 2:
        urgency += 1.0
    elif hp <= 4:
        urgency += 0.6
    elif hp <= 7:
        urgency += 0.25

    if no_water_days >= 2:
        urgency += 1.0
    elif no_water_days == 1:
        urgency += 0.45

    late_game = day >= 8
    if late_game:
        urgency += 0.2

    if hp <= 2 or no_water_days >= 2:
        emergency_bid = max(92.0, highest_prev + 3.0)
        return min(float(budget), emergency_bid)

    if float(supply) >= 23 and hp >= 8 and no_water_days == 0:
        return min(float(budget), 8.0)

    if float(supply) >= 20 and highest_prev >= 120 and hp >= 6:
        return min(float(budget), 14.0)

    base = 16.0 + 22.0 * scarcity + 18.0 * urgency

    if highest_prev > 0:
        if highest_prev >= 120:
            if hp >= 6 and no_water_days == 0 and float(supply) >= 18:
                target = 15.0
            else:
                target = 0.72 * highest_prev + 4.0
        elif highest_prev >= 85:
            target = 0.78 * highest_prev + 5.0
        else:
            target = max(base, highest_prev + 2.5)
    else:
        target = base

    if rich_aggressive >= 2 and hp >= 6 and no_water_days == 0 and float(supply) >= 18:
        target = min(target, 18.0)

    reserve_floor = 0.0
    if day <= 7:
        reserve_floor = 120.0
    elif day <= 9:
        reserve_floor = 60.0

    affordable = float(budget) - reserve_floor
    if affordable < 0:
        affordable = float(budget) * 0.45

    bid = min(target, affordable, float(budget))

    if bid < 0:
        bid = 0.0

    if hp <= 4 or no_water_days >= 1:
        bid = max(bid, min(float(budget), 35.0 + 15.0 * scarcity))

    return float(max(0.0, bid))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = day_context['day']

    # Alive opponents
    alive = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive.append((oid, o))

    # If no one alive, spend enough to ensure we don't run out
    if not alive:
        return min(my_status['budget'], DAILY_SALARY * 0.4)

    # Read yesterday bids from previous_trace only
    yesterday_bids = []
    yesterday_pressures = []
    for _, o in alive:
        prev = o.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                yesterday_bids.append(float(b))
            except Exception:
                pass
        # Approximate pressure: if they had low hp after, assume they were close to failing
        hp_after = prev.get('hp_after', None)
        if hp_after is not None:
            try:
                yesterday_pressures.append((float(hp_after), float(b) if b is not None else 0.0))
            except Exception:
                pass

    # Base bid depends on our hp
    my_hp = float(my_status['hp'])
    my_budget = float(my_status['budget'])

    # Determine supply-driven urgency: if supply is closer to MIN, competition is higher.
    # Use a conservative scaling.
    supply_ratio = (supply - MIN_SUPPLY) / (MAX_SUPPLY - MIN_SUPPLY) if MAX_SUPPLY != MIN_SUPPLY else 0.5
    supply_ratio = max(0.0, min(1.0, supply_ratio))
    # competition_factor higher when supply is low
    competition_factor = 1.15 - 0.3 * supply_ratio

    # If opponents were bidding high yesterday, they likely continue to fight for water.
    # Use their max bid as a proxy.
    if yesterday_bids:
        max_prev_bid = max(yesterday_bids)
        # Thresholds relative to DAILY_SALARY
        high_thresh = DAILY_SALARY * 1.15  # ~103.5
        very_high_thresh = DAILY_SALARY * 1.6  # ~144

        # If we are low hp, we must secure water; otherwise, undercut.
        if my_hp <= 2.0:
            target = DAILY_SALARY * 0.95 * competition_factor
            # If someone was extremely high yesterday, match closer
            if max_prev_bid >= very_high_thresh:
                target = DAILY_SALARY * 1.05 * competition_factor
            return min(my_budget, max(1.0, target))

        if max_prev_bid >= very_high_thresh:
            # They were desperate; bid moderately to avoid losing entirely.
            target = DAILY_SALARY * 0.75 * competition_factor
            return min(my_budget, max(1.0, target))

        if max_prev_bid >= high_thresh:
            # Bid slightly below their likely continuation to win some allocation
            target = DAILY_SALARY * 0.62 * competition_factor
            return min(my_budget, max(1.0, target))

        # If yesterday bids were low, we can bid less.
        target = DAILY_SALARY * 0.48 * competition_factor
        return min(my_budget, max(1.0, target))

    # Fallback if no bid info
    if my_hp <= 2.0:
        return min(my_budget, max(1.0, DAILY_SALARY * 0.9))
    return min(my_budget, max(1.0, DAILY_SALARY * 0.55))

def get_bid(day_context, my_status, opponents_status):
    DAILY_SALARY = 80
    WATER_REQ = 7
    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    avg_prev_bid = sum(yesterday_bids) / len(yesterday_bids) if yesterday_bids else 60.0

    if my_status['hp'] <= 3:
        bid = min(my_status['budget'], DAILY_SALARY * 1.2)
    else:
        bid = min(my_status['budget'], max(DAILY_SALARY * 0.7, avg_prev_bid * 1.05))

    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140
    alive = {k: v for k, v in opponents_status.items() if v['alive']}
    prev_bids = []
    for opp in alive.values():
        trace = opp.get('previous_trace')
        if trace and trace['bid'] is not None:
            prev_bids.append(trace['bid'])
    max_prev = max(prev_bids) if prev_bids else 0

    hp = my_status['hp']
    budget = my_status['budget']
    supply = day_context['supply']
    day = day_context['day']

    # Base bid based on HP and yesterday's max bid
    if hp <= 2:
        bid = min(budget, DAILY_SALARY * 0.95)
    elif hp <= 4:
        bid = min(budget, max(DAILY_SALARY * 0.6, max_prev + 2))
    else:
        if max_prev > DAILY_SALARY * 0.85:
            bid = min(budget, DAILY_SALARY * 0.3)
        else:
            bid = min(budget, DAILY_SALARY * 0.5)

    # Adjust if dehydrated
    if my_status['no_water_days'] > 0:
        bid = max(bid, DAILY_SALARY * 0.7)

    return min(budget, max(0, bid))
